import { Provide } from '@src/framework/runtime-context';
import { Component, ComponentInterface, Element, h, Host, Prop } from '@stencil/core';
import { SideNavigationContext, SideNavigationContextValue } from './context';
import { Slot, Slots } from '@src/framework/decorators';

const prefix = 'side-navigation';

/**
 * @slot title - Slot for the main title text of the side navigation.
 * @slot banner - Slot for placing additional components between the title section and the main navigation content.
 * @slot footer - Slot for content to be placed at the bottom of the side navigation panel.
 * @slot default - Slot for the main navigation items rendered inside the side navigation content area.
 * @part base - The base container of the component.
 */
@Component({
  styleUrl: 'styles/ks-side-navigation.scss',
  tag: 'ks-side-navigation',
  shadow: true,
})
export class KsSideNavigation implements ComponentInterface {
  @Element() el!: HTMLKsSideNavigationElement;

  @Provide({ context: SideNavigationContext }) private context: SideNavigationContextValue = {
    active: null,
    onActivate: (value: string) => {
      this.context = {
        ...this.context,
        active: value,
      };
    },
  };

  /** Whether the side navigation is floating or default mode. */
  @Prop() variant: 'default' | 'floating' = 'default';

  @Slot({ slotname: 'title' }) private titleSlots?: Slots;
  @Slot({ slotname: 'banner' }) private bannerSlots?: Slots;
  @Slot({ slotname: 'footer' }) private footerSlots?: Slots;

  render() {
    return (
      <Host class="KsSideNavigation">
        <div
          class={{
            [prefix]: true,
            [`${prefix}--floating`]: this.variant === 'floating',
          }}
          part="base"
        >
          {this.titleSlots && (
            <div class={`${prefix}__title`}>
              <slot name="title" />
            </div>
          )}

          {this.bannerSlots && <slot name="banner" />}

          <div class={`${prefix}__content`}>
            <slot />
          </div>

          {this.footerSlots && <slot name="footer" />}
        </div>
      </Host>
    );
  }
}
